"use strict";(self.webpackChunkshareme=self.webpackChunkshareme||[]).push([["3738"],{86797(n){n.exports=JSON.parse('{"tag":{"label":"manual","permalink":"/shareme/other/tags/manual","allTagsPath":"/shareme/other/tags","count":11,"items":[{"id":"servo/wecon/01-precautions","title":"01 L\u01B0u \xfd An to\xe0n v\xe0 Khuy\u1EBFn ngh\u1ECB Thi\u1EBFt b\u1ECB B\u1EA3o v\u1EC7 (Precautions)","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 01 L\u01B0u \xfd an to\xe0n khi l\u1EAFp \u0111\u1EB7t, \u0111\u1EA5u n\u1ED1i, v\u1EADn h\xe0nh v\xe0 khuy\u1EBFn ngh\u1ECB ch\u1ECDn CB / RCD cho Servo VD3E Series.","permalink":"/shareme/other/servo/wecon/01-precautions"},{"id":"servo/wecon/02-product-information","title":"02 Th\xf4ng tin S\u1EA3n ph\u1EA9m v\xe0 Th\xf4ng s\u1ED1 K\u1EF9 thu\u1EADt (Product Information)","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 02 Quy t\u1EAFc \u0111\u1EB7t m\xe3 hi\u1EC7u, c\u1EA5u t\u1EA1o v\xe0 th\xf4ng s\u1ED1 k\u1EF9 thu\u1EADt b\u1ED9 \u0111i\u1EC1u khi\u1EC3n Servo VD3E Series & \u0110\u1ED9ng c\u01A1 Servo WD/WE.","permalink":"/shareme/other/servo/wecon/02-product-information"},{"id":"servo/wecon/03-installation","title":"03 K\xedch th\u01B0\u1EDBc C\u01A1 kh\xed v\xe0 H\u01B0\u1EDBng d\u1EABn L\u1EAFp \u0111\u1EB7t (Installation)","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 03 B\u1EA3n v\u1EBD k\xedch th\u01B0\u1EDBc c\u01A1 kh\xed v\xe0 y\xeau c\u1EA7u m\xf4i tr\u01B0\u1EDDng l\u1EAFp \u0111\u1EB7t cho b\u1ED9 \u0111i\u1EC1u khi\u1EC3n Servo VD3E Series v\xe0 \u0111\u1ED9ng c\u01A1 Servo WD/WE.","permalink":"/shareme/other/servo/wecon/03-installation"},{"id":"servo/wecon/04-wiring","title":"04 S\u01A1 \u0111\u1ED3 \u0110\u1EA5u n\u1ED1i M\u1EA1ch \u0111\u1ED9ng l\u1EF1c, Encoder, I/O v\xe0 Truy\u1EC1n th\xf4ng (Wiring)","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 04 H\u01B0\u1EDBng d\u1EABn \u0111\u1EA5u n\u1ED1i m\u1EA1ch \u0111\u1ED9ng l\u1EF1c 220V/380V, c\xe1p \u0111\u1ED9ng c\u01A1, c\xe1p phanh t\u1EEB, c\xe1p Encoder tuy\u1EC7t \u0111\u1ED1i, gi\u1EAFc \u0111i\u1EC1u khi\u1EC3n CN2 v\xe0 c\u1ED5ng EtherCAT CN5/CN6.","permalink":"/shareme/other/servo/wecon/04-wiring"},{"id":"servo/wecon/05-panel","title":"05 B\u1EA3ng \u0111i\u1EC1u khi\u1EC3n LED v\xe0 Thao t\xe1c C\xe0i \u0111\u1EB7t (Panel Operation)","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 05 H\u01B0\u1EDBng d\u1EABn gi\u1EA3i m\xe3 hi\u1EC3n th\u1ECB LED 5 ch\u1EEF s\u1ED1, c\xe0i \u0111\u1EB7t tham s\u1ED1, ch\u1EA1y th\u1EED JOG v\xe0 kh\xf4i ph\u1EE5c c\xe0i \u0111\u1EB7t g\u1ED1c tr\xean Servo VD3E Series.","permalink":"/shareme/other/servo/wecon/05-panel"},{"id":"servo/wecon/06-communication-network-configuration","title":"06 C\u1EA5u h\xecnh M\u1EA1ng truy\u1EC1n th\xf4ng EtherCAT v\xe0 M\xe1y tr\u1EA1ng th\xe1i CiA 402","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 06 Ki\u1EBFn tr\xfac truy\u1EC1n th\xf4ng EtherCAT (CoE), \xe1nh x\u1EA1 RPDO/TPDO, \u0111\u1ED3ng h\u1ED3 ph\xe2n t\xe1n DC v\xe0 s\u01A1 \u0111\u1ED3 m\xe1y tr\u1EA1ng th\xe1i CiA 402 tr\xean Servo VD3E Series.","permalink":"/shareme/other/servo/wecon/06-communication-network-configuration"},{"id":"servo/wecon/07-operation-running","title":"07 V\u1EADn h\xe0nh C\u01A1 b\u1EA3n, C\xe1c Ch\u1EBF \u0111\u1ED9 \u0110i\u1EC1u khi\u1EC3n (CSP, CSV, CST, PT, HM) & Touch Probe","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 07 H\u01B0\u1EDBng d\u1EABn v\u1EADn h\xe0nh c\u01A1 b\u1EA3n, c\u1EA5u h\xecnh phanh t\u1EEB, t\u1EEB \u0111i\u1EC1u khi\u1EC3n 6040h/6041h, c\xe1c ch\u1EBF \u0111\u1ED9 CSP, CSV, CST, PT, 30 ph\u01B0\u01A1ng ph\xe1p v\u1EC1 g\u1ED1c Homing (6098h) v\xe0 \u0111\u1EA7u d\xf2 Touch Probe.","permalink":"/shareme/other/servo/wecon/07-operation-running"},{"id":"servo/wecon/09-adjustments","title":"09 Nh\u1EADn d\u1EA1ng Qu\xe1n t\xednh, Tinh ch\u1EC9nh \u0110\u1ED9 l\u1EE3i (Gain) v\xe0 Ch\u1ED1ng Rung C\u1ED9ng h\u01B0\u1EDFng","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 09 H\u01B0\u1EDBng d\u1EABn nh\u1EADn d\u1EA1ng t\u1EF7 s\u1ED1 qu\xe1n t\xednh t\u1EA3i, ch\u1EC9nh \u0111\u1ECBnh \u0111\u1ED9 l\u1EE3i t\u1EF1 \u0111\u1ED9ng/th\u1EE7 c\xf4ng, \u0111i\u1EC1u khi\u1EC3n b\xe1m m\xf4 h\xecnh v\xe0 b\u1ED9 l\u1ECDc Notch Filter tr\xean Servo VD3E Series.","permalink":"/shareme/other/servo/wecon/09-adjustments"},{"id":"servo/wecon/10-malfunctions","title":"10 Ch\u1EA9n \u0111o\xe1n S\u1EF1 c\u1ED1, B\u1EA3ng M\xe3 l\u1ED7i (Er.xx) v\xe0 C\u1EA3nh b\xe1o (A-xx)","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 10 Quy tr\xecnh ph\xe2n lo\u1EA1i, ch\u1EA9n \u0111o\xe1n nguy\xean nh\xe2n v\xe0 h\u01B0\u1EDBng d\u1EABn x\u1EED l\xfd to\xe0n b\u1ED9 m\xe3 l\u1ED7i (Er.01~Er.65) v\xe0 m\xe3 c\u1EA3nh b\xe1o (A-80~A-93) tr\xean Servo VD3E Series.","permalink":"/shareme/other/servo/wecon/10-malfunctions"},{"id":"servo/wecon/11-appendix","title":"11 Ph\u1EE5 l\u1EE5c B\u1EA3ng T\u1ED5ng h\u1EE3p T\u1EEB \u0111i\u1EC3n \u0110\u1ED1i t\u01B0\u1EE3ng, M\xe3 l\u1ED7i, C\xe1p v\xe0 Ti\xeau chu\u1EA9n EMC","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: 11 Ph\u1EE5 l\u1EE5c b\u1EA3ng tra c\u1EE9u nhanh T\u1EEB \u0111i\u1EC3n \u0111\u1ED1i t\u01B0\u1EE3ng (1000h, 2000h, 6000h), ch\u1EE9c n\u0103ng DI/DO, m\xe3 l\u1ED7i Er/A, m\xe3 c\xe1p \u0111\u1ED9ng l\u1EF1c/Encoder v\xe0 ti\xeau chu\u1EA9n EMC/CE.","permalink":"/shareme/other/servo/wecon/11-appendix"},{"id":"servo/wecon/tong-quan-servo-wecon-vd3e","title":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt Servo M\u1EA1ng EtherCAT WECON VD3E Series","description":"T\xe0i li\u1EC7u k\u1EF9 thu\u1EADt chu\u1EA9n h\xe3ng WECON: S\u1ED5 tay h\u01B0\u1EDBng d\u1EABn s\u1EED d\u1EE5ng b\u1ED9 \u0111i\u1EC1u khi\u1EC3n \u0111\u1ED9ng c\u01A1 Servo m\u1EA1ng EtherCAT d\xf2ng VD3E Series (Chu\u1EA9n CiA 402).","permalink":"/shareme/other/servo/wecon/"}],"unlisted":false}}')}}]);